with w as(select * from public.works where id=any(array[423,323,452,800,499,559,261,561,854,419,554,295,246,3028,585,774,627,2826,589]::bigint[])),a as(select * from public.authors where id in(select author_id from w)) select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(t) order by id) from w t),'authors',(select jsonb_agg(to_jsonb(t) order by id) from a t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789023428756','9789064032295','9789048848607','9789046705186','9789021467979','9789024561858','9789024578221','9789022981948','9789002277986','9789077895092','9789026339936','9789020542585','9789044369236','9789464822199','9789022530450','9789044366365','9789022564240','9789022550151','9789032521479']::text[]) or open_library_edition_id=any(array['OL59692847M','OL34490134M','OL32890293M','OL26227565M','OL46528670M','OL25429536M','OL60473832M','OL32366726M','OL60598610M','OL25426216M','OL61554425M','OL61200456M','OL60650924M','OL61339469M','OL45867977M','OL60309759M','OL40205682M','OL32358465M','OL61057863M']::text[])),'metadata',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from public.catalog_edition_metadata t where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from public.catalog_work_descriptions t where work_id in(select id from w))) as preflight;
